The Enumerator struct is a custom enumerator that doesn't allocate on the heap, which is important for MMO scale networking. 

Here is the full Enumerator struct:

```csharp
public struct Enumerator : IEnumerator<T>
{
    readonly SyncList<T> list;
    int index;
    public T Current { get; private set; }

    public Enumerator(SyncList<T> list)
    {
        this.list = list;
        index = 0;
        Current = default(T);
    }

    public bool MoveNext()
    {
        while (index < list.objects.Count)
        {
            Current = list.objects[index];
            index++;
            return true;
        }
        return false;
    }

    public void Reset()
    {
        index = 0;
        Current = default(T);
    }

    public void Dispose()
    {
    }
}
