private static void checkForDuplicatePkgs(Configuration cf,
                                          Function<String, ClassLoader> clf)
{
    Set<Module> defined = new HashSet<>();
    cf.modules().forEach(module -> {
        String moduleName = module.name();
        ClassLoader loader = clf.apply(moduleName);
        if (loader!= null) {
            Module definedModule = defined.stream()
                   .filter(m -> m.name().equals(moduleName) && m.loader() == loader)
                   .findFirst()
                   .orElse(null);
            if (definedModule!= null) {
                throw new LayerInstantiationException("Duplicate package: " + moduleName);
            }
            defined.add(new Module(moduleName, loader));
        }
    });
}

private static void checkForJavaBase(Configuration cf,
                                     Function<String, ClassLoader> clf)
{
    cf.modules().forEach(module -> {
        if (module.name().equals("java.base")) {
            throw new LayerInstantiationException("java.base module is not allowed in the configuration");
        }
        module.packages().forEach(pkg -> {
            if (pkg.name().equals("java") || pkg.name().startsWith("java.")) {
                throw new LayerInstantiationException("java package is not allowed in the module");
            }
        });
    });
}

private static void checkForPlatformClassLoader(Function<String, ClassLoader> clf)
{
    Objects.requireNonNull(clf);
    for (String moduleName : clf.apply(null).getDefinedPackages()) {
        if (moduleName.equals("java.base")) {
            throw new LayerInstantiationException("Platform class loader cannot be used for java.base module");
        }
    }
}

public static AutoNumberingScheme createAutoNumberingScheme(final String schemeName,
                                                            final String schemeClassName,
                                                            final String formatName,
                                                            final boolean isNumericOnly,
                                                            final int   tableNumber,
                                                            final Collection collection)
{
    AutoNumberingScheme autoNumberingScheme = new AutoNumberingScheme();
    autoNumberingScheme.initialize();
    autoNumberingScheme.setSchemeName(schemeName);
    autoNumberingScheme.setSchemeClassName(schemeClassName);
    autoNumberingScheme.setFormatName(formatName);
    autoNumberingScheme.setIsNumericOnly(isNumericOnly);
    autoNumberingScheme.setTableNumber(tableNumber);
    collection.addReference(autoNumberingScheme, "numberingSchemes");
    collection.getNumberingSchemes().add(autoNumberingScheme);
    persist(autoNumberingScheme);
    return autoNumberingScheme;
}

