encodeBytesToBytes( source, off, len, options ) {
        // Streams
        java.io.ByteArrayOutputStream  baos  = null; 
        java.io.OutputStream           b64os = null;
        java.util.zip.GZIPOutputStream gzos  = null;
        java.io.ByteArrayOutputStream  encoded = null;

        try {
            // ObjectOutputStream -> (GZIP) -> Base64 -> ByteArrayOutputStream
            encoded = new java.io.ByteArrayOutputStream();
            b64os = new Base64.OutputStream( encoded, ENCODE | options );
            if( (options & GZIP)!= 0 ){
                // Gzip
                gzos = new java.util.zip.GZIPOutputStream(b64os);
                gzos.write( source, off, len );
            } else {
                // Not gzipped
                b64os.write( source, off, len );
            }
            b64os.flush();
            encoded.flush();
        }   // end try
        catch( java.io.IOException e ) {
            // Catch it and then throw it immediately so that
            // the finally{} block is called for cleanup.
            throw e;
        }   // end catch
        finally {
            try{ gzos.close();  } catch( Exception e ){}
            try{ b64os.close(); } catch( Exception e ){}
            try{ encoded.close(); } catch( Exception e ){}
        }   // end finally

        // Return value according to relevant encoding.
        return encoded.toByteArray();
    }   // end encodeBytesToBytes

