            if (xmlReader.Name == "DockingManager")
            {
                IsAnimationEnabled = XmlConvert.ToBoolean(xmlReader.GetAttribute("IsAnimationEnabled"));
                RestoreLayout = XmlConvert.ToBoolean(xmlReader.GetAttribute("IsRestoreLayout"));
