                if (xmlReader.HasAttributes && xmlReader.GetAttribute("SelectedIndex")!= null)
                {
                    pane.SelectedIndex = XmlConvert.ToInt32(xmlReader.GetAttribute("SelectedIndex"));
                }
                if (xmlReader.HasAttributes && xmlReader.GetAttribute("IsAutoHidden")!= null)
                {
