private void samplesToInterpolationCoefficient1D(
        final double[] c,
        final int degree,
        final double tolerance)
{
    double[] z = new double[0];
    double lambda = 1.0;
    switch (degree) {
        case 3:
            z = new double[1];
            z[0] = Math.sqrt(3.0) - 2.0;
            break;
        case 7:
            z = new double[4];
            z[0] = 1.0 / 7.0;
            z[1] = 1.0 / 7.0;
            z[2] = 1.0 / 7.0;
            z[3] = 1.0 / 7.0;
            break;
        default:
            z = new double[1];
            z[0] = 1.0;
    }

    double[] coefficients = new double[c.length];
    for (int i = 0; i < c.length; i++) {
        coefficients[i] = c[i];
    }

    for (int i = 0; i < coefficients.length; i++) {
        for (int j = 0; j < z.length; j++) {
            coefficients[i] += z[j] * c[i + j + 1];
        }
    }

    for (int i = 0; i < coefficients.length; i++) {
        for (int j = 0; j < z.length; j++) {
            coefficients[i] += z[j] * c[i - j - 1];
        }
    }

    // Apply tolerance
    if (tolerance > 0) {
        for (int i = 0; i < coefficients.length; i++) {
            if (Math.abs(coefficients[i]) < tolerance) {
                coefficients[i] = 0.0;
            }
        }
    }

    System.arraycopy(coefficients, 0, c, 0, c.length);
}
