      if (mx == -1) {
        target.setX(target.getX() - 1);
      } else if (mx == 1) {
        target.setX(target.getX() + 1);
      }
      if (my == -1) {
        target.setY(target.getY() - 1);
      } else if (my == 1) {
        target.setY(target.getY() + 1);
      }
    }
    return result;
