            else if (extensions.Contains("GL_ARB_texture_rg"))
            {
                R16Formats &= ~_KTX_R16_FORMATS_SNORM;
            }
            else
            {
                R16Formats = _KTX_NO_R16_FORMATS;
            }
        }
    }
